/* @autogenerated */
import { CommonModule } from '@angular/common';
import { Component, computed, input, signal } from '@angular/core';
import { ReactiveFormsModule } from '@angular/forms';
import { MatIconModule } from '@angular/material/icon';
import { TranslocoModule } from '@jsverse/transloco';
import { BaseEditable } from '../base-editable';
import { EditableHiddenMarkComponent } from '../editable-hidden-mark/editable-hidden-mark.component';

@Component({
  selector: 'editable-rating',
  standalone: true,
  imports: [CommonModule, ReactiveFormsModule, MatIconModule, TranslocoModule, EditableHiddenMarkComponent],
  providers: BaseEditable.getValidableAccessorProvider(EditableRatingComponent),
  templateUrl: './editable-rating.component.html',
  styleUrls: ['./editable-rating.component.scss'],
})
export class EditableRatingComponent extends BaseEditable<number> {
  max = input<number>(5);
  icon = input<string>('star');
  halfSteps = input<boolean>(false);
  color = input<'primary' | 'accent' | 'warn'>('accent');

  hovered = signal<number | null>(null);

  stars = computed(() => Array.from({ length: this.max() }, (_, i) => i + 1));

  displayValue = computed(() => this.hovered() ?? this.value() ?? 0);

  iconFor(star: number): string {
    const val = this.displayValue();
    if (this.halfSteps()) {
      if (val >= star) return this.icon();
      if (val >= star - 0.5) return this.icon() + '_half';
    } else {
      if (val >= star) return this.icon();
    }
    return this.icon() + '_border';
  }

  onClick(star: number, event: MouseEvent): void {
    if (this.disabled()) return;
    const value = this.halfSteps() ? this.resolveHalf(star, event) : star;
    const current = this.value();
    // click on same full star → clear
    this.updateValue(current === value ? null : value);
  }

  onMouseMove(star: number, event: MouseEvent): void {
    if (this.disabled()) return;
    this.hovered.set(this.halfSteps() ? this.resolveHalf(star, event) : star);
  }

  onMouseLeave(): void {
    this.hovered.set(null);
  }

  onKeyDown(event: KeyboardEvent): void {
    if (this.disabled()) return;
    const step = this.halfSteps() ? 0.5 : 1;
    const current = this.value() ?? 0;
    if (event.key === 'ArrowRight' || event.key === 'ArrowUp') {
      event.preventDefault();
      this.updateValue(Math.min(current + step, this.max()));
    } else if (event.key === 'ArrowLeft' || event.key === 'ArrowDown') {
      event.preventDefault();
      this.updateValue(Math.max(current - step, 0) || null);
    }
  }

  override validate(_: any) {
    const val = this.value();
    if (val === null || val === undefined) return null;
    if (val < 0) return { ratingMin: true };
    if (val > this.max()) return { ratingMax: true };
    return null;
  }

  private resolveHalf(star: number, event: MouseEvent): number {
    const el = event.currentTarget as HTMLElement;
    const { left, width } = el.getBoundingClientRect();
    return event.clientX - left < width / 2 ? star - 0.5 : star;
  }
}
